'use strict'
const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const vm = require('node:vm')
const ts = require('typescript')
const raiz = path.resolve(__dirname,'..')
const read = relative => fs.readFileSync(path.join(raiz,relative),'utf8')
const routeSrc = read('lib/reciboImpressaoRota.ts')
const { outputText } = ts.transpileModule(routeSrc,{ compilerOptions:{ module:ts.ModuleKind.CommonJS, target:ts.ScriptTarget.ES2020 } })
const mod = { exports:{} }
vm.runInNewContext(outputText,{module:mod,exports:mod.exports})
const { rotaReciboAutenticado } = mod.exports
assert.equal(rotaReciboAutenticado('/financeiro/recibo/receber/abc-123'),true)
assert.equal(rotaReciboAutenticado('/financeiro/recibo/pagar/abc-123'),true)
assert.equal(rotaReciboAutenticado('/financeiro/recibo/consolidado'),true)
assert.equal(rotaReciboAutenticado('/financeiro/recibo/consolidado/'),true)
assert.equal(rotaReciboAutenticado('/clientes/abc/vendas/def/recibo/ghi'),true)
assert.equal(rotaReciboAutenticado('/financeiro/contas-receber'),false)
assert.equal(rotaReciboAutenticado('/clientes/abc'),false)
assert.equal(rotaReciboAutenticado('/financeiro/recibo/receber'),false)
assert.equal(rotaReciboAutenticado('/financeiro/recibo/receber/abc/editar'),false)

const gate = read('components/AuthGate.tsx')
const botaoChat = read('components/BotaoChatGlobal.tsx')
const comp = read('components/financeiro/ReciboImpressao.tsx')
const reciboUnico = read('app/financeiro/recibo/[tipo]/[id]/page.tsx')
const reciboConsolidado = read('app/financeiro/recibo/consolidado/page.tsx')
assert.ok(gate.indexOf('if (!autenticado) return null') < gate.indexOf('if (rotaReciboAutenticado(pathname)) return <SetorRouteGuard><Cliente360RouteGuard>{children}</Cliente360RouteGuard></SetorRouteGuard>'))
assert.ok(gate.indexOf('if (rotaReciboAutenticado(pathname))') < gate.indexOf('return <><AppShell>'))
assert.match(botaoChat,/rotaReciboAutenticado\(pathname\)\)return null/)
assert.match(comp,/@page \{ size: A4 portrait; margin: 12mm; \}/)
assert.match(comp,/\.no-print, \.atlas-sidebar-shell, \.atlas-topbar/)
assert.match(comp,/\.atlas-recibo-papel \{/)
assert.match(comp,/box-shadow: none !important/)
assert.match(comp,/break-inside: avoid-page/)
assert.match(comp,/ref=\{papelRef\}/)
assert.match(comp,/html2canvas\(papelRef\.current,/)
assert.match(comp,/format: 'a4'/)
assert.match(comp,/window\.print\(\)/)
assert.match(reciboUnico,/atlas-recibo-pagina/)
assert.match(reciboConsolidado,/atlas-recibo-pagina/)
assert.match(reciboUnico,/<div className="no-print/)
assert.match(reciboConsolidado,/<div className="no-print/)
assert.match(read('app/clientes/[id]/vendas/[vendaId]/recibo/[recebimentoId]/page.tsx'), /print:min-h-0/)
console.log('OK — impressão A4 mostra somente o recibo, sem AppShell/menu/usuário; individual, consolidado e PDF preservados.')
